{
  "schema_version": "1.0",
  "prompt_version": "1.3",
  "options": {
    "organizational": {
      "name": {
       "text": "Organisatorische Klärung von Zuständigkeit und Bestätigungsregeln in der Partnerabstimmung.",
       "source_ids": ["process.name", "process.cause_hypotheses"],
       "assumptions": ["Unklare Zuständigkeiten sind eine unbestätigte Ursachenhypothese."],
       "open_evidence": ["Ob unklare Zuständigkeit tatsächlich ursächlich wirkt, ist nicht belegt."],
       "uncertainty": {"level": "high", "reason": "Ursachenhypothese unbestätigt und Quellen nicht validiert."}
      },
      "description": {
       "text": "Beobachtet ist: Der lokale Leistungspartner fragt Busunternehmen und Reiseleitung an; der Zusatzpreis bleibt offen und der Treffpunkt ist nicht bestätigt. Laut Geschäftsregel ist eine Anfrage kein bestätigter Auftrag und fehlende Rückmeldung keine Zustimmung. Die organisatorische Option klärt daher Zuständigkeit und Bestätigungsregeln, ohne die vermutete Ursache als belegt zu behandeln.",
       "source_ids": ["process.current_flow", "process.business_rules", "process.roles", "process.cause_hypotheses"],
       "assumptions": ["Zuständigkeitsklärung adressiert die vermutete Ursache."],
       "open_evidence": ["Kein Nachweis, dass unklare Zuständigkeit die Unsicherheit verursacht."],
       "uncertainty": {"level": "high", "reason": "Wirkung auf unbestätigte Ursache gestützt."}
      },
      "expected_value": {
       "text": "Erwarteter Nutzen rein qualitativ: klarere Verantwortlichkeit und nachvollziehbare Bestätigung. Eine konkrete Nutzen- oder Zielkennzahl ist in den Quellen nicht belegt.",
       "source_ids": ["process.business_rules", "process.baseline_metrics"],
       "assumptions": [],
       "open_evidence": ["Baseline ist unbekannt und nicht bestätigt."],
       "uncertainty": {"level": "high", "reason": "Keine belegte Nutzenkennzahl vorhanden."}
      },
      "bottleneck_coverage": {
       "text": "Setzt an beiden genannten Engpässen an: offener Zusatzpreis des Busunternehmens und fehlende Treffpunktbestätigung der Reiseleitung. Dies geschieht über festgelegte Klärungs- und Bestätigungsregeln.",
       "source_ids": ["process.bottlenecks", "process.business_rules"],
       "assumptions": ["Regelklärung reduziert die Engpässe."],
       "open_evidence": ["Wirksamkeitsnachweis fehlt."],
       "uncertainty": {"level": "high", "reason": "Engpasswirkung nicht belegt."}
      },
      "data_requirements": {
       "text": "Benötigt die genannten Datenobjekte: Änderungsanfrage SYN-D-01 sowie Rückmeldungen von Busunternehmen und Reiseleitung. Konkrete Datenformate sind nicht belegt.",
       "source_ids": ["process.data_objects"],
       "assumptions": [],
       "open_evidence": ["Datenformate und Ablagestrukturen unbekannt."],
       "uncertainty": {"level": "medium", "reason": "Datenobjekte benannt, Formate offen."}
      },
      "application_impact": {
       "text": "Betrifft vor allem die bekannten Kommunikationswege Telefon und schriftliche Mitteilungen. Konkrete Programme sind unbekannt.",
       "source_ids": ["process.systems", "process.roles"],
       "assumptions": [],
       "open_evidence": ["Anwendungsänderungen sind nicht belegt."],
       "uncertainty": {"level": "medium", "reason": "Systemlandschaft nur unkonkret bekannt."}
      },
      "integration_impact": {
       "text": "Keine belegte Systemintegration erforderlich, da die Maßnahme organisatorisch auf Rollen und Regeln wirkt. Systeme sind nur unkonkret bekannt.",
       "source_ids": ["process.systems", "process.roles"],
       "assumptions": ["Die organisatorische Klärung kommt ohne neue Systemintegration aus."],
       "open_evidence": ["Integrationserfordernisse sind nicht belegt."],
       "uncertainty": {"level": "high", "reason": "Integration nicht belegt."}
      },
      "technology_constraints": {
       "text": "Keine Technologievorgaben aus Quellen belegt. Bekannt sind nur Telefon und schriftliche Mitteilungen als Kommunikationswege.",
       "source_ids": ["process.systems"],
       "assumptions": [],
       "open_evidence": ["Technische Randbedingungen unbelegt."],
       "uncertainty": {"level": "medium", "reason": "Technikrahmen unbekannt."}
      },
      "risks": {
       "text": "Risiko: Regeln könnten die vermutete, aber unbestätigte Ursache nicht treffen. Zusatzpreis und Treffpunkt können weiter offen bleiben.",
       "source_ids": ["process.cause_hypotheses", "process.bottlenecks", "process.exceptions"],
       "assumptions": [],
       "open_evidence": ["Kein Nachweis der Ursache-Wirkung."],
       "uncertainty": {"level": "high", "reason": "Ursache unbelegt."}
      },
      "architecture_fit": {
       "text": "Passt als organisatorische Klärung ohne belegte Architekturänderung. Ob sie zum Zielzustand passt, ist ohne validierte Architekturquellen offen.",
       "source_ids": ["process.roles", "process.systems"],
       "assumptions": [],
       "open_evidence": ["Zielarchitektur nicht belegt."],
       "uncertainty": {"level": "high", "reason": "Architekturfit nicht belegbar."}
      }
    },
    "rule_automation": {
      "name": {
       "text": "Regelbasierte Status- und Rückmeldeautomatisierung – vorrangig Prüfung vorhandener Standardsoftware.",
       "source_ids": ["process.name", "process.systems"],
       "assumptions": [],
       "open_evidence": ["Ob Standardsoftware die Funktion bereits bietet, ist nicht belegt."],
       "uncertainty": {"level": "high", "reason": "Standardsoftware-Funktionsumfang unbekannt."}
      },
      "description": {
       "text": "Regelbasiert könnte der Status 'keine Rückmeldung = keine Zustimmung' geführt und bei offenem Zusatzpreis nachgefasst werden. Zuerst ist zu prüfen, ob vorhandene Standardsoftware dies leistet; eine eigene Automation ist keine Vorgabe. Die Ursache der Unsicherheit bleibt dabei unbestätigt.",
       "source_ids": ["process.current_flow", "process.business_rules", "process.exceptions", "process.systems"],
       "assumptions": ["Regelbasierte Erinnerungen adressieren die Engpässe."],
       "open_evidence": ["Funktionsumfang vorhandener Standardsoftware unbekannt."],
       "uncertainty": {"level": "high", "reason": "Ursache und Standardsoftware-Fähigkeit offen."}
      },
      "expected_value": {
       "text": "Erwarteter Nutzen rein qualitativ: frühzeitigere oder vollständigere Rückmeldungen sind denkbar. Eine belegte Nutzenkennzahl fehlt.",
       "source_ids": ["process.baseline_metrics", "process.bottlenecks"],
       "assumptions": [],
       "open_evidence": ["Nutzen nicht belegt."],
       "uncertainty": {"level": "high", "reason": "Keine belegte Kennzahl."}
      },
      "bottleneck_coverage": {
       "text": "Adressiert offenen Zusatzpreis und fehlende Treffpunktbestätigung über Regel- und Erinnerungslogik. Die Wirksamkeit ist nicht belegt.",
       "source_ids": ["process.bottlenecks", "process.business_rules"],
       "assumptions": [],
       "open_evidence": ["Wirksamkeit unbelegt."],
       "uncertainty": {"level": "high", "reason": "Wirkung nicht belegt."}
      },
      "data_requirements": {
       "text": "Benötigt die genannten Datenobjekte: Änderungsanfrage SYN-D-01 sowie Rückmeldungen von Busunternehmen und Reiseleitung. Weitere für Automatisierung nötige Felder sind nicht belegt.",
       "source_ids": ["process.data_objects"],
       "assumptions": [],
       "open_evidence": ["Zusätzliche Datenanforderungen nicht dokumentiert."],
       "uncertainty": {"level": "high", "reason": "Datenbedarf unvollständig belegt."}
      },
      "application_impact": {
       "text": "Betrifft die bekannten Kommunikationswege Telefon und schriftliche Mitteilungen. Falls Standardsoftware genutzt wird, könnten diese Systeme betroffen sein; konkrete Programme sind unbekannt.",
       "source_ids": ["process.systems"],
       "assumptions": [],
       "open_evidence": ["Programme und Funktionsumfang unbekannt."],
       "uncertainty": {"level": "high", "reason": "Anwendungslandschaft unbekannt."}
      },
      "integration_impact": {
       "text": "Integration wäre nur erforderlich, falls Standardsoftware angebunden werden muss. Eine belegte Integrationsanforderung liegt nicht vor.",
       "source_ids": ["process.systems"],
       "assumptions": [],
       "open_evidence": ["Integrationsbedarf unbelegt."],
       "uncertainty": {"level": "high", "reason": "Integration nicht belegt."}
      },
      "technology_constraints": {
       "text": "Technische Randbedingungen sind nicht belegt. Unbekannt ist, welche Regel- oder Workflow-Funktionen vorhanden sind.",
       "source_ids": ["process.systems"],
       "assumptions": [],
       "open_evidence": ["Standardsoftware-Fähigkeiten offen."],
       "uncertainty": {"level": "high", "reason": "Technikvorgaben fehlen."}
      },
      "risks": {
       "text": "Risiko: Automatisierung einer unbestätigten Ursache. Die Regel 'fehlende Rückmeldung = keine Zustimmung' darf nicht als Zustimmung fehlinterpretiert werden.",
       "source_ids": ["process.business_rules", "process.cause_hypotheses", "process.exceptions"],
       "assumptions": [],
       "open_evidence": ["Ursache unbelegt."],
       "uncertainty": {"level": "high", "reason": "Ursache und Regelwirkung nicht belegt."}
      },
      "architecture_fit": {
       "text": "Eine regelbasierte Ergänzung kann nur bedingt beurteilt werden, da Zielarchitektur und Standardsoftware-Landschaft unbekannt sind.",
       "source_ids": ["process.systems"],
       "assumptions": [],
       "open_evidence": ["Architekturinformationen fehlen."],
       "uncertainty": {"level": "high", "reason": "Architekturfit nicht belegbar."}
      }
    },
    "assistant": {
      "name": {
       "text": "Assistenzsystem zur Bündelung und Erinnerung von Partnerrückmeldungen – KI nur bei belegtem Zusatznutzen.",
       "source_ids": ["process.name", "process.current_flow"],
       "assumptions": [],
       "open_evidence": ["KI-Mehrwert gegenüber einfachem Klärweg nicht belegt."],
       "uncertainty": {"level": "high", "reason": "Zusatznutzen unbelegt."}
      },
      "description": {
       "text": "Beobachtet ist, dass Rückmeldungen von Busunternehmen und Reiseleitung ausstehen und der Organisator unsicher ist. Ein einfacher Klärweg über Zuständigkeit und Regeln könnte ausreichen; ein belegter Zusatznutzen von KI gegenüber diesem Weg ist in den Quellen nicht erkennbar.",
       "source_ids": ["process.current_flow", "process.diagnostic_observations", "process.cause_hypotheses"],
       "assumptions": [],
       "open_evidence": ["KI-Nutzen nicht belegt."],
       "uncertainty": {"level": "high", "reason": "KI-Mehrwert offen."}
      },
      "expected_value": {
       "text": "Erwarteter Nutzen rein qualitativ: Bündelung und Sichtbarkeit von Rückmeldungen sind denkbar. Eine belegte Nutzen- oder Zielkennzahl fehlt.",
       "source_ids": ["process.baseline_metrics"],
       "assumptions": [],
       "open_evidence": ["Keine Kennzahl belegt."],
       "uncertainty": {"level": "high", "reason": "Nutzen nicht belegt."}
      },
      "bottleneck_coverage": {
       "text": "Kann Rückmeldungen bündeln und Engpässe sichtbar machen. Ohne belegte Ursache bleibt die Wirkung auf offenen Zusatzpreis und fehlende Treffpunktbestätigung bedingt.",
       "source_ids": ["process.bottlenecks", "process.cause_hypotheses"],
       "assumptions": [],
       "open_evidence": ["Wirkung auf Engpässe unbelegt."],
       "uncertainty": {"level": "high", "reason": "Ursache unbelegt."}
      },
      "data_requirements": {
       "text": "Benötigt die genannten Datenobjekte: Änderungsanfrage SYN-D-01 sowie Rückmeldungen von Busunternehmen und Reiseleitung. Eine für Assistenz nötige Datenbasis ist nicht spezifiziert.",
       "source_ids": ["process.data_objects"],
       "assumptions": [],
       "open_evidence": ["Datenbasis nicht spezifiziert."],
       "uncertainty": {"level": "high", "reason": "Datenbedarf unklar."}
      },
      "application_impact": {
       "text": "Setzt auf den bekannten Kommunikationswegen Telefon und schriftliche Mitteilungen auf. Konkrete Programme sind unbekannt.",
       "source_ids": ["process.systems"],
       "assumptions": [],
       "open_evidence": ["Anwendungsänderungen nicht belegt."],
       "uncertainty": {"level": "medium", "reason": "Systeme nur unkonkret bekannt."}
      },
      "integration_impact": {
       "text": "Eine Integration in unbekannte Systeme wäre erforderlich; eine belegte Anforderung liegt nicht vor.",
       "source_ids": ["process.systems"],
       "assumptions": [],
       "open_evidence": ["Integrationsbedarf unbelegt."],
       "uncertainty": {"level": "high", "reason": "Integration nicht belegt."}
      },
      "technology_constraints": {
       "text": "KI-spezifische technische Randbedingungen sind nicht belegt. Bekannt sind nur Telefon und schriftliche Mitteilungen als Kommunikationswege.",
       "source_ids": ["process.systems"],
       "assumptions": [],
       "open_evidence": ["KI-Randbedingungen unbelegt."],
       "uncertainty": {"level": "high", "reason": "Technikvorgaben fehlen."}
      },
      "risks": {
       "text": "Risiko: KI ohne belegten Zusatznutzen. Fehlende Rückmeldungen dürfen nicht als Zustimmung fehlinterpretiert werden.",
       "source_ids": ["process.business_rules", "process.cause_hypotheses", "process.exceptions"],
       "assumptions": [],
       "open_evidence": ["KI-Nutzen und Ursache nicht belegt."],
       "uncertainty": {"level": "high", "reason": "Nutzen und Ursache offen."}
      },
      "architecture_fit": {
       "text": "Der Architekturfit ist bedingt, da Zielarchitektur und KI-Vorgaben fehlen.",
       "source_ids": ["process.systems"],
       "assumptions": [],
       "open_evidence": ["Architektur- und KI-Vorgaben fehlen."],
       "uncertainty": {"level": "high", "reason": "Architekturfit nicht belegbar."}
      }
    }
  }
}
